import { readFileSync } from 'node:fs';
import { checkDynamicUses } from './scripts/conformance/static/check-imports.js';
const path = 'scripts/benchmarks/a19-correction-paths.mjs';
const inventory = JSON.parse(readFileSync('scripts/conformance/static/allowlist.json', 'utf8'));
const allow = inventory.allow.filter(entry => entry.path === path);
if (allow.length !== 1) throw new Error('Expected exactly one reviewed benchmark inventory row');
const report = checkDynamicUses(process.cwd(), [path], { ...inventory, allow });
console.log(JSON.stringify({ scope: [path], passed: report.errors.length === 0, ...report }, null, 2));
if (report.errors.length) process.exitCode = 1;
